window.AUTH=window.AUTH||{};window.AUTH["21-857"]={"d":"21-857","id":"2022/21-857","n":"Jones v. Hendrix","briefs":[{"k":"petitioner","label":"Brief of petitioner Marcus DeAngelo Jones","date":"2022-07-14","url":"https://www.supremecourt.gov/DocketPDF/21/21-857/230051/20220714094933784_21-857_Brief%20for%20Petitioner.pdf","side":"pet","n":80},{"k":"respondent","label":"Brief of respondent Dewayne Hendrix, Warden supporting affirmance","date":"2022-08-08","url":"https://www.supremecourt.gov/DocketPDF/21/21-857/233024/20220808182056765_21-857bsUnitedStates.pdf","side":"res","n":67},{"k":"reply","label":"Reply of petitioner Marcus DeAngelo Jones","date":"2022-10-12","url":"https://www.supremecourt.gov/DocketPDF/21/21-857/242898/20221012075828192_No.%2021-857_Reply%20Brief%20for%20Petitioner.pdf","side":"pet","n":38}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/599us1r42_2b35.pdf","tr":true,"items":[{"t":"case","label":"Boumediene v. Bush","cite":"553 U.S. 723","y":2008,"id":"2007/06-1195","sc":1,"op":4,"ar":1,"sum":"Noting that the purpose of § 2255 was “to strengthen, rather than dilute, the writ's protections” and further recognizing that the saving clause served that purpose.","sumSrc":"opinion","by":{"0":"14, 34, 46","1":"15, 18","2":"5, 12"}},{"t":"case","label":"Bousley v. United States","cite":"523 U.S. 614","y":1998,"id":"1997/96-8516","sc":1,"op":3,"ar":5,"sum":"The Court held that, although Bousley's claim was procedurally defaulted, Bousley may be entitled to a hearing on the merits of it if he makes the necessary showing to relieve the default.","sumSrc":"Oyez","by":{"0":"9, 35","1":"21, 23, 24","2":"11, 21"}},{"t":"case","label":"Bunkley v. Florida","cite":"538 U.S. 835","y":2003,"id":"2002/02-8636","sc":1,"sum":"The Court held that the state court must consider whether an inmate’s pocketknife fit within the “common pocketknife” exception at the time his conviction became final.","sumSrc":"Oyez","by":{"0":"44"}},{"t":"case","label":"Burns v. Wilson","cite":"346 U.S. 137","y":1953,"id":"scdb/1952-107","sc":1,"sum":"Judgment affirmed. Pp. 138-146. 91 U. S. App. D. C. 208, 202 F. 2d 335, affirmed. The District Court dismissed petitioners' applications for writs of habeas corpus. 104 F. Supp. 310, 312. The Court of Appeals affirmed. 91 U. S. App. D. C. 208, 202 F. 2d 335. This Court granted certiorari. 344 U. S. 903. At the time of the argument, February 5, 1953, Wilson, present Secretary of Defense, was substituted for Lovett, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Castille v. Peoples","cite":"489 U.S. 346","y":1989,"id":"1988/87-1602","sc":1,"sum":"Following the Pennsylvania Superior Court's affirmance, on direct appeal, of respondent's conviction of assault, robbery, and related crimes, he filed with the State Supreme Court successive unsuccessful petitions for allocatur, which, under state law, can be granted in the court's discretion \"only when there are special and important reasons therefor.\" Respondent next filed a petition for federal habeas relief, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"26"}},{"t":"case","label":"Chazen v. Marske","cite":"938 F.3d 851","y":2019,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/938/851/","op":3,"ar":2,"by":{"0":"10"}},{"t":"case","label":"Clark v. Suarez Martinez","cite":"543 U.S. 371","y":2005,"id":"2004/03-878","sc":1,"sum":"The Court said the requirement that immigrants be detained no longer than reasonably necessary for deportation applied to both admissible and inadmissible immigrants. Because readmission to Cuba was unforeseeable, the detentions of Martinez and Benitez were unreasonable.","sumSrc":"Oyez","by":{"0":"33"}},{"t":"case","label":"Clinton v. Goldsmith","cite":"526 U.S. 529","y":1999,"id":"1998/98-347","sc":1,"op":1,"sum":"The Court held that because the Court of Appeals for the Armed Forces' resort to the All Writs Act was neither in aid of its strictly circumscribed jurisdiction to review court-martial findings and sentences nor \"necessary or appropriate\" in light of a servicemember's alternative opportunities to seek relief, that court lacked jurisdiction to issue an injunction against dropping Goldsmith from the Air Force rolls.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Corley v. United States","cite":"556 U.S. 303","y":2009,"id":"2008/07-10441","sc":1,"sum":"The Court found that voluntary confessions made more than six hours after arrest before the person has been presented before judicial officers are inadmissible.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Davis v. United States","cite":"417 U.S. 333","y":1974,"id":"1973/72-1454","sc":1,"op":13,"sum":"Holding a claim of legal error based on an intervening change in statutory interpretation cognizable under § 2255.","sumSrc":"opinion","by":{"0":"2, 45","1":"passim","2":"4"}},{"t":"case","label":"Deckert v. Independence Shares Corps.","cite":"311 U.S. 282","y":1940,"id":"scdb/1940-011","sc":1,"sum":"(1) An appeal to the Circuit Court of Appeals from an interlocutory order granting an injunction was authorized by § 129 of the Judicial Code and was not premature. P. 286. (2) Upon such appeal the Circuit Court of Appeals could properly determine the correctness of'the District Court's denial of motions Statement of the Case. to dismiss the bill, although normally such denial would be appealable only after a final …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Demore v. Kim","cite":"538 U.S. 510","y":2003,"id":"2002/01-1491","sc":1,"op":2,"sum":"The Court held, 6-3, that the Immigration and Nationality Act does not deprive the federal courts of jurisdiction to grant habeas relief to aliens challenging their detention under section 1226(c) and, 5-4, that detention during removal proceedings is a constitutionally permissible part of that process.","sumSrc":"Oyez","by":{"0":"29"}},{"t":"case","label":"Duckworth v. Serrano","cite":"454 U.S. 1","y":1981,"id":"1981/80-2041","sc":1,"sum":"The Court of Appeals was obligated to dismiss respondent's petition because obvious constitutional errors, no less than obscure transgressions, are subject to the well-settled requirement, codified in the federal habeas statute, 28 U. S. C. §§ 2254(b) and (c), that a state prisoner must normally exhaust state remedies before a writ of habeas corpus can be granted by the federal courts. Creating an exception to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13"}},{"t":"case","label":"Duncan v. Walker","cite":"533 U.S. 167","y":2001,"id":"2000/00-121","sc":1,"op":6,"sum":"The Court held that an federal habeas corpus petition is not an \"application for State post-conviction or other collateral review\" within the meaning of 28 USC section 2244(d)(2). \"Section 2244(d)(2) therefore did not toll the limitation period during the pendency of [Walker's] first federal habeas petition,\" wrote Justice O'Connor. \"[I]f the statute were construed so as to give applications for federal review the same tolling effect as applications for state collateral review, then [section] 2244(d)(2) would furnish little incentive for individuals to seek relief from the state courts before filing federal habeas petitions,\" concluded Justice O'Connor.","sumSrc":"Oyez","by":{"0":"16"}},{"t":"case","label":"Edwards v. United States","cite":"1987 WL 7562","y":1987,"court":"E.D. N.Y.","op":1,"by":{"0":"32"}},{"t":"case","label":"Edwards v. Vannoy","cite":"141 S. Ct. 1547","y":2021,"id":"2020/19-5807","sc":1,"op":2,"sum":"The jury-unanimity rule announced in Ramos v. Louisiana, 590 U. S. ___, does not apply retroactively on federal collateral review.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"11, 14, 35"}},{"t":"case","label":"Egle v. Egle","cite":"715 F.2d 999","y":1983,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/715/999/","by":{"0":"32"}},{"t":"case","label":"Felker v. Turpin","cite":"518 U.S. 651","y":1996,"id":"1995/95-8836","sc":1,"op":4,"ar":3,"sum":"The unanimous Court held that the Act's creation of an appellate panel, charged with reviewing all second or successive habeas applications, is not unconstitutional. The Act simply transfers the duty of habeas review from the district courts to an appellate panel.","sumSrc":"Oyez","by":{"0":"42","1":"27, 44, 45, 46"}},{"t":"case","label":"Fiore v. White","cite":"531 U.S. 225","y":2001,"id":"1999/98-942","sc":1,"op":1,"sum":"After certifying an question of state law to the Pennsylvania Supreme Court, the U.S. Supreme Court held that Fiore's conviction was not covered by the statute at issue and thus violated the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"0":"15, 44","1":"46"}},{"t":"case","label":"George v. McDonough","cite":"142 S. Ct. 1953","y":2022,"id":"2021/21-234","sc":1,"op":1,"sum":"The invalidation of a Department of Veterans Affairs regulation after a veteran’s benefits decision becomes final cannot support a claim for collateral relief permitting revision of that decision based on “clear and unmistakable error” under 38 U. S. C. §§5109A and 7111.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"19"}},{"t":"case","label":"Herrera v. Collins","cite":"506 U.S. 390","y":1993,"id":"1992/91-7328","sc":1,"op":2,"sum":"The Court held that the rejection of Herrera’s petition did not constitute cruel and unusual punishment under the Eighth Amendment. Chief Justice Rehnquist concluded that evidence of Herrera’s actual innocence was not relevant to his petition for a writ of habeas corpus absent some constitutional violation by the state of Texas.","sumSrc":"Oyez","by":{"0":"46"}},{"t":"case","label":"Hillsborough Twp. v. Cromwell","cite":"326 U.S. 620","y":1946,"id":"scdb/1945-084","sc":1,"sum":"1. Under the Declaratory Judgment Act, Judicial Code § 274 (d), a federal district court has jurisdiction to entertain a suit for the purpose of determining the validity of a state tax assessment under the due process and equal protection clauses of the Fourteenth Amendment, where the constitutional rights of the complainant can not be protected adequately by proceedings in the state courts. Great Lakes Dredge & …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Lee v. Sanders","cite":"943 F.3d 1145","y":2019,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/943/1145/","by":{"0":"8, 9"}},{"t":"case","label":"Loughrin v. United States","cite":"573 U.S. 351","y":2014,"id":"2013/13-316","sc":1,"sum":"The Court held that, to find someone guilty of bank fraud, only one of the two bank fraud statutes must be met, not both.","sumSrc":"Oyez","by":{"0":"19, 25"}},{"t":"case","label":"Marino v. Ragen","cite":"332 U.S. 561","y":1947,"id":"scdb/1947-018","sc":1,"op":2,"sum":"Petitioner pro se.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"McCarthan v. Director of Goodwill Indus.- Suncoast, Inc.","cite":"851 F.3d 1076","y":2017,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/851/1076/","op":3,"by":{"0":"passim","1":"10, 31, 37, 39, 40, 41"}},{"t":"case","label":"Montgomery v. Louisiana","cite":"577 U.S. 190","y":2016,"id":"2015/14-280","sc":1,"sum":"The Court held that the Supreme Court’s decision in Miller v. Alabama, which prohibits sentencing schemes that impose a punishment of mandatory life without parole for juvenile offenders convicted of homicide, applied retroactively.","sumSrc":"Oyez","by":{"0":"35"}},{"t":"case","label":"Morrisey v. Brewer","cite":"408 U.S. 471","y":1972,"id":"1971/71-5103","sc":1,"sum":"The Court held that due process required Iowa to include a preliminary hearing to determine probable cause for the parole revocations of Morrissey and Booker.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Pettibone v. United States","cite":"148 U.S. 197","y":1893,"id":"scdb/1892-140","sc":1,"sum":"In a prosecution for conspiracy, corruptly and by threats, and force to obstruct the due administration of justice in a Circuit Court of'the-United States, the combination of minds for the unlawful purpose and the overt act in effectuation of that purpose must appear charged in the indictment.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"36-37"}},{"t":"case","label":"Powell v. Texas","cite":"392 U.S. 514","y":1968,"id":"1967/405","sc":1,"sum":"The plurality found that the record did not prove that alcoholics were totally unable to control their alcohol consumption. The law prohibiting public intoxication did not punish Powell for his alcoholism, but for his being drunk in a public location. Chief Justice Earl Warren, Justice Hugo L. Black, and Justice John M. Harlan joined in the plurality.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"Powerex Corp. v. Reliant Energy Servs., Inc.","cite":"551 U.S. 224","y":2007,"id":"2006/05-85","sc":1,"op":4,"sum":"The Court ruled 7-2 that the Ninth Circuit lacked jurisdiction to review the District Court's remand order. The Court relied on 28 U.S.C. 1447(d), which precludes appellate review of remands based on lack of subject-matter jurisdiction.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Preiser v. Rodriguez","cite":"411 U.S. 475","y":1973,"id":"1972/71-1369","sc":1,"sum":"When a state prisoner challenges the fact or duration of his physical imprisonment and by way of relief seeks a determination that he is entitled to immediate release or a speedier release, his sole federal remedy is a writ of habeas corpus.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Prost v. Anderson","cite":"636 F.3d 578","y":2011,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/636/578/","op":3,"sum":"Holding that § 2255(e) does not permit recourse to § 2241 in these circumstances.","sumSrc":"opinion","by":{"0":"passim","1":"11, 15, 16, 41"}},{"t":"case","label":"Reed Elsevier, Inc. v. Muchnick","cite":"559 U.S. 154","y":2010,"id":"2009/08-103","sc":1,"sum":"The Court held that the registration requirement of Section 411(a) of the Copyright Act is a precondition to filing a copyright infringement claim.","sumSrc":"Oyez","by":{"0":"37"}},{"t":"case","label":"Rehaif v. United States","cite":"139 S. Ct. 2191","y":2019,"id":"2018/17-9560","sc":1,"op":15,"ar":5,"sum":"In a prosecution under 18 U. S. C. §922(g) and §924(a)(2), the Government must prove both that the defendant knew he possessed a firearm and that he knew he belonged to the relevant category of persons barred from possessing a firearm.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"passim","1":"5, 8, 12, 33, 34, 35","2":"21"}},{"t":"case","label":"Rivers v. Roadway Express, Inc.","cite":"511 U.S. 298","y":1994,"id":"1993/92-938","sc":1,"sum":"Section 101 does not apply to a case that arose before it was enacted.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42","2":"17"}},{"t":"case","label":"Robinson v. California","cite":"370 U.S. 660","y":1962,"id":"1961/554","sc":1,"op":1,"sum":"The Court held that laws criminalizing the \"illness\" of narcotic addiction inflicted cruel and unusual punishment in violation of the Eighth and Fourteenth Amendments.","sumSrc":"Oyez","by":{"0":"45, 46"}},{"t":"case","label":"Runkle v. United States","cite":"122 U.S. 543","y":1887,"id":"scdb/1886-306","sc":1,"sum":"Article 65 of tbe Articles of War in the act of April 10,1806, 2 Stat. 358,367, “ for the government of the armies of the United States,” enacted that “ neither shall any sentence.of a general court-martial, in time of peace, extending to the loss of life, or the dismission of a commissioned officer, or which shall, either in time of peace or war, respect a general officer, be carried into execution until after the …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Shinn v. Ramirez","cite":"142 S. Ct. 1718","y":2022,"id":"2021/20-1009","sc":1,"op":1,"sum":"Under 28 U. S. C. §2254(e)(2), a federal habeas court may not conduct an evidentiary hearing or otherwise consider evidence beyond the state-court record based on the ineffective assistance of state postconviction counsel.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"35"}},{"t":"case","label":"Solum v. Helm","cite":"463 U.S. 277","y":1983,"id":"1982/82-492","sc":1,"sum":"Since all of Helm's prior offenses, including his current check-writing conviction, had been \"relatively minor\" and were not crimes against people, Justice Powell held that Helm had \"received the penultimate sentence (South Dakota did not have the death penalty) for relatively minor criminal conduct.\" Powell concluded that Helm was treated more harshly than the state's most violent criminals.","sumSrc":"Oyez","by":{"0":"15"}},{"t":"case","label":"Spaulding v. Taylor","cite":"336 F.2d 192","y":1964,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/336/192/","op":3,"by":{"0":"32","2":"4"}},{"t":"case","label":"Taggart v. Lorenzen","cite":"139 S. Ct. 1795","y":2019,"id":"2018/18-489","sc":1,"sum":"A creditor may be held in civil contempt for violating a bankruptcy court’s discharge order if there is no fair ground of doubt as to whether the order barred the creditor’s conduct.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"19"}},{"t":"case","label":"United States v. Addonizio","cite":"442 U.S. 178","y":1979,"id":"1978/78-156","sc":1,"op":2,"sum":"A federal prisoner's allegation that a postsentencing change in the policies of the United States Parole Commission has prolonged his actual imprisonment beyond the period intended by the sentencing judge will not support a collateral attack on the original sentence under 28 U. S. C. § 2255.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"37","1":"14, 17, 19, 20, 21"}},{"t":"case","label":"United States v. Hall","cite":"98 U.S. 343","y":1878,"id":"scdb/1878-082","sc":1,"sum":"Congress has, under the Constitution, power to declare that the embezzlement or fraudulent conversion to his own use by a guardian of the money which he, on behalf of his wards, has received from the government as a pension due to them, is an offence against the United States, and to vest the proper Circuit Court with jurisdiction to try and punish him therefor.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"36","1":"45"}},{"t":"case","label":"United States v. Hayman","cite":"342 U.S. 205","y":1952,"id":"scdb/1951-024","sc":1,"op":14,"sum":"The District Court erred in determining the factual issues raised by respondent's motion under § 2255 without notice to respondent and without his presence.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"35, 46","1":"passim","2":"2"}},{"t":"case","label":"United States v. Jones","cite":"185 Fed. Appx. 541","y":2006,"court":"8th Cir.","url":"https://www.courtlistener.com/c/Fed.%20Appx./185/541/","op":1,"by":{"0":"7"}},{"t":"case","label":"United States v. Jones","cite":"403 F.3d 604","y":2005,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/403/604/","op":2,"by":{"0":"7"}},{"t":"case","label":"United States v. Jones","cite":"266 F.3d 804","y":2001,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/266/804/","op":3,"sum":"Rejecting sufficiency-of-the-evidence challenge “that [Jones] did not have knowledge of his prior felony convictions [because t]he government need not prove knowledge, but only the fact of a prior felony conviction.”.","sumSrc":"brief:0","by":{"0":"5, 6, 26","2":"17, 22, 23"}},{"t":"case","label":"United States v. Kind","cite":"194 F.3d 900","y":1999,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/194/900/","op":1,"by":{"0":"6"}},{"t":"case","label":"United States v. Lanier","cite":"520 U.S. 259","y":1997,"id":"1996/95-1717","sc":1,"sum":"Authored by Justice David Souter, the Court ruled that the standard of notice that the Court of Appeals employed was higher than the Constitution requires and too demanding.","sumSrc":"Oyez","by":{"0":"42"}},{"t":"case","label":"United States v. New Bedford Bridge","cite":"27 F. Cas. 91","y":1847,"court":"D. Mass.","url":"https://www.courtlistener.com/c/F.%20Cas./27/91/","sum":"Stating “it is considered that no acts done against [the government] can usually be punished as crimes without specific legislation” for in those cases the court does not “have jurisdiction of the offence”.","sumSrc":"brief:0","by":{"0":"3, 36"}},{"t":"case","label":"United States ex rel. Dunlap v. Black","cite":"128 U.S. 40","y":1888,"id":"scdb/1888-010","sc":1,"sum":"The courts will not interfere by mandamus with the executive officers of the government in the exercise of their ordinary official duties, even where those duties require an interpretation of the law; no appellate powerbeing given them for that purpose.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Wisconsin Cent. Ltd. v. United States","cite":"138 S. Ct. 2067","y":2018,"id":"2017/17-530","sc":1,"sum":"The Court decided that employee stock options are not taxable “compensation” under the Railroad Retirement Tax Act because they are not “money remuneration.”","sumSrc":"Oyez","by":{"0":"16-17"}},{"t":"case","label":"Wooden v. United States","cite":"142 S. Ct. 1063","y":2022,"id":"2021/20-5279","sc":1,"sum":"Wooden’s ten burglary offenses arising from a single criminal episode did not occur on different “occasions” and thus count as only one prior conviction under the Armed Career Criminal Act.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"14, 30"}},{"t":"case","label":"Ysleta Del Sur Pueblo v. Texas","cite":"142 S. Ct. 1929","y":2022,"id":"2021/20-493","sc":1,"sum":"The federal legislation at issue—the Ysleta del Sur and Alabama and Coushatta Indian Tribes of Texas Restoration Act—bans as a matter of federal law on tribal lands only those gaming activities also banned in Texas.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"30"}},{"t":"const","label":"Article I, Section 9, Clause 2","clauses":[["habeas","Suspension Clause (Habeas Corpus)"]],"text":"The Privilege of the Writ of Habeas Corpus shall not be suspended, unless when in Cases of Rebellion or Invasion the public Safety may require it.","by":{"0":"34"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"0":"43"}},{"t":"const","label":"Amendment VIII","clauses":[["eighth-amendment","Eighth Amendment"]],"text":"Excessive bail shall not be required, nor excessive fines imposed, nor cruel and unusual punishments inflicted.","by":{"0":"45","1":"46"}},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(a)(6)","(g)","(g)(1)","(a)(6)(1994)","(g)(5)","(g)(5)(A)"],"stext":{"head":"§922. Unlawful acts","paras":[[0,"(a) It shall be unlawful—"],[1,"(1) for any person—"],[2,"(A) except a licensed importer, licensed manufacturer, or licensed dealer, to engage in the business of importing, manufacturing, or dealing in firearms, or in the course of such business to ship, transport, or receive any firearm in interstate or foreign commerce; or"],[2,"(B) except a licensed importer or licensed manufacturer, to engage in the business of importing or manufacturing ammunition, or in the course of such business, to ship, transport, or receive any ammunition in interstate or foreign commerce;"],[1,"(2) for any importer, manufacturer, dealer, or collector licensed under the provisions of this chapter to ship or transport in interstate or foreign commerce any firearm to any person other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, except that—"],[2,"(A) this paragraph and subsection (b)(3) shall not be held to preclude a licensed importer, licensed manufacturer, licensed dealer, or licensed collector from returning a firearm or replacement firearm of the same kind and type to a person from whom it was received; and this paragraph shall not be held to preclude an individual from mailing a firearm owned in compliance with Federal, State, and local law to a licensed importer, licensed manufacturer, licensed dealer, or licensed collector;"],[2,"(B) this paragraph shall not be held to preclude a licensed importer, licensed manufacturer, or licensed dealer from depositing a firearm for conveyance in the mails to any officer, employee, agent, or watchman who, pursuant to the provisions of section 1715 of this title, is eligible to receive through the mails pistols, revolvers, and other firearms capable of being concealed on the person, for use in connection with his official duty; and"],[2,"(C) nothing in this paragraph shall be construed as applying in any manner in the District of Columbia, the Commonwealth of Puerto Rico, or any possession of the United States differently than it would apply if the District of Columbia, the Commonwealth of Puerto Rico, or the possession were in fact a State of the United States;"],[1,"(3) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector to transport into or receive in the State where he resides (or if the person is a corporation or other business entity, the State where it maintains a place of business) any firearm purchased or otherwise obtained by such person outside that State, except that this paragraph (A) shall not preclude any person who lawfully acquires a firearm by bequest or intestate succession in a State other than his State of residence from transporting the firearm into or receiving it in that State, if it is lawful for such person to purchase or possess such firearm in that State, (B) shall not apply to the transportation or receipt of a firearm obtained in conformity with subsection (b)(3) of this section, and (C) shall not apply to the transportation of any firearm acquired in any State prior to the effective date of this chapter;"],[1,"(4) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, to transport in interstate or foreign commerce any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity;"],[1,"(5) for any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) to transfer, sell, trade, give, transport, or deliver any firearm to any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) who the transferor knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the transferor resides; except that this paragraph shall not apply to (A) the transfer, transportation, or delivery of a firearm made to carry out a bequest of a firearm to, or an acquisition by intestate succession of a firearm by, a person who is permitted to acquire or possess a firearm under the laws of the State of his residence, and (B) the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(6) for any person in connection with the acquisition or attempted acquisition of any firearm or ammunition from a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, knowingly to make any false or fictitious oral or written statement or to furnish or exhibit any false, fictitious, or misrepresented identification, intended or likely to deceive such importer, manufacturer, dealer, or collector with respect to any fact material to the lawfulness of the sale or other disposition of such firearm or ammunition under the provisions of this chapter;"],[1,"(7) for any person to manufacture or import armor piercing ammunition, unless—"],[2,"(A) the manufacture of such ammunition is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) the manufacture of such ammunition is for the purpose of exportation; or"],[2,"(C) the manufacture or importation of such ammunition is for the purpose of testing or experimentation and has been authorized by the Attorney General;"],[1,"(8) for any manufacturer or importer to sell or deliver armor piercing ammunition, unless such sale or delivery—"],[2,"(A) is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) is for the purpose of exportation; or"],[2,"(C) is for the purpose of testing or experimentation and has been authorized by the Attorney General; 1"],[1,"(9) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, who does not reside in any State to receive any firearms unless such receipt is for lawful sporting purposes."],[0,"(b) It shall be unlawful for any licensed importer, licensed manufacturer, licensed dealer, or licensed collector to sell or deliver—"],[1,"(1) any firearm or ammunition to any individual who the licensee knows or has reasonable cause to believe is less than eighteen years of age, and, if the firearm, or ammunition is other than a shotgun or rifle, or ammunition for a shotgun or rifle, to any individual who the licensee knows or has reasonable cause to believe is less than twenty-one years of age;"],[1,"(2) any firearm to any person in any State where the purchase or possession by such person of such firearm would be in violation of any State law or any published ordinance applicable at the place of sale, delivery or other disposition, unless the licensee knows or has reasonable cause to believe that the purchase or possession would not be in violation of such State law or such published ordinance;"],[1,"(3) any firearm to any person who the licensee knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the licensee's place of business is located, except that this paragraph (A) shall not apply to the sale or delivery of any rifle or shotgun to a resident of a State other than a State in which the licensee's place of business is located if the transferee meets in person with the transferor to accomplish the transfer, and the sale, delivery, and receipt fully comply with the legal conditions of sale in both such States (and any licensed manufacturer, importer or dealer shall be presumed, for purposes of this subparagraph, in the absence of evidence to the contrary, to have had actual knowledge of the State laws and published ordinances of both States), and (B) shall not apply to the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(4) to any person any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity; and"],[1,"(5) any firearm or armor-piercing ammunition to any person unless the licensee notes in his records, required to be kept pursuant to section 923 of this chapter, the name, age, and place of residence of such person if the person is an individual, or the identity and principal and local places of business of such person if the person is a corporation or other business entity."],[0,"Paragraphs (1), (2), (3), and (4) of this subsection shall not apply to transactions between licensed importers, licensed manufacturers, licensed dealers, and licensed collectors. Paragraph (4) of this subsection shall not apply to a sale or delivery to any research organization designated by the Attorney General."],[0,"(c) In any case not otherwise prohibited by this chapter, a licensed importer, licensed manufacturer, or licensed dealer may sell a firearm to a person who does not appear in person at the licensee's business premises (other than another licensed importer, manufacturer, or dealer) only if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/922?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§922. Unlawful acts","tname":"Crimes and Criminal Procedure","by":{"0":"5, passim, 5","1":"3, 4, 35, 5, 33, 42, 3, 4, 33, 33, 33"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(a)(1)(B)","(a)(2)","(e)","(a)","(e)(1)(1994)","(e)(1)"],"stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§924. Penalties","tname":"Crimes and Criminal Procedure","by":{"0":"5, 37, 5","1":"42, 33, 4, 3, 4, 33"}},{"t":"usc","label":"28 U.S.C. § 384","url":"https://www.law.cornell.edu/uscode/text/28/384","by":{"0":"28"}},{"t":"usc","label":"28 U.S.C. § 1405","url":"https://www.law.cornell.edu/uscode/text/28/1405","by":{"0":"33"}},{"t":"usc","label":"28 U.S.C. § 2241","url":"https://www.law.cornell.edu/uscode/text/28/2241","subs":["(c)"],"stext":{"head":"§2241. Power to grant writ","paras":[[0,"(a) Writs of habeas corpus may be granted by the Supreme Court, any justice thereof, the district courts and any circuit judge within their respective jurisdictions. The order of a circuit judge shall be entered in the records of the district court of the district wherein the restraint complained of is had."],[0,"(b) The Supreme Court, any justice thereof, and any circuit judge may decline to entertain an application for a writ of habeas corpus and may transfer the application for hearing and determination to the district court having jurisdiction to entertain it."],[0,"(c) The writ of habeas corpus shall not extend to a prisoner unless—"],[1,"(1) He is in custody under or by color of the authority of the United States or is committed for trial before some court thereof; or"],[1,"(2) He is in custody for an act done or omitted in pursuance of an Act of Congress, or an order, process, judgment or decree of a court or judge of the United States; or"],[1,"(3) He is in custody in violation of the Constitution or laws or treaties of the United States; or"],[1,"(4) He, being a citizen of a foreign state and domiciled therein is in custody for an act done or omitted under any alleged right, title, authority, privilege, protection, or exemption claimed under the commission, order or sanction of any foreign state, or under color thereof, the validity and effect of which depend upon the law of nations; or"],[1,"(5) It is necessary to bring him into court to testify or for trial."],[0,"(d) Where an application for a writ of habeas corpus is made by a person in custody under the judgment and sentence of a State court of a State which contains two or more Federal judicial districts, the application may be filed in the district court for the district wherein such person is in custody or in the district court for the district within which the State court was held which convicted and sentenced him and each of such district courts shall have concurrent jurisdiction to entertain the application. The district court for the district wherein such an application is filed in the exercise of its discretion and in furtherance of justice may transfer the application to the other district court for hearing and determination."],[0,"(e)(1) No court, justice, or judge shall have jurisdiction to hear or consider an application for a writ of habeas corpus filed by or on behalf of an alien detained by the United States who has been determined by the United States to have been properly detained as an enemy combatant or is awaiting such determination."],[0,"(2) Except as provided in paragraphs (2) and (3) of section 1005(e) of the Detainee Treatment Act of 2005 (10 U.S.C. 801 note), no court, justice, or judge shall have jurisdiction to hear or consider any other action against the United States or its agents relating to any aspect of the detention, transfer, treatment, trial, or conditions of confinement of an alien who is or was detained by the United States and has been determined by the United States to have been properly detained as an enemy combatant or is awaiting such determination."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2241?type=usc&year=mostrecent&link-type=html"},"op":33,"head":"§2241. Power to grant writ","tname":"Judiciary and Judicial Procedure","by":{"0":"passim, 31","1":"16","2":"passim"}},{"t":"usc","label":"28 U.S.C. § 2254","url":"https://www.law.cornell.edu/uscode/text/28/2254","subs":["(b)","(b)(1)(B)(ii)"],"by":{"0":"26, 26"}},{"t":"usc","label":"28 U.S.C. § 2255","url":"https://www.law.cornell.edu/uscode/text/28/2255","subs":["(a)","(e)","(h)","(h)(2)","(h)(1)"],"stext":{"head":"§2255. Federal custody; remedies on motion attacking sentence","paras":[[0,"(a) A prisoner in custody under sentence of a court established by Act of Congress claiming the right to be released upon the ground that the sentence was imposed in violation of the Constitution or laws of the United States, or that the court was without jurisdiction to impose such sentence, or that the sentence was in excess of the maximum authorized by law, or is otherwise subject to collateral attack, may move the court which imposed the sentence to vacate, set aside or correct the sentence."],[0,"(b) Unless the motion and the files and records of the case conclusively show that the prisoner is entitled to no relief, the court shall cause notice thereof to be served upon the United States attorney, grant a prompt hearing thereon, determine the issues and make findings of fact and conclusions of law with respect thereto. If the court finds that the judgment was rendered without jurisdiction, or that the sentence imposed was not authorized by law or otherwise open to collateral attack, or that there has been such a denial or infringement of the constitutional rights of the prisoner as to render the judgment vulnerable to collateral attack, the court shall vacate and set the judgment aside and shall discharge the prisoner or resentence him or grant a new trial or correct the sentence as may appear appropriate."],[0,"(c) A court may entertain and determine such motion without requiring the production of the prisoner at the hearing."],[0,"(d) An appeal may be taken to the court of appeals from the order entered on the motion as from a final judgment on application for a writ of habeas corpus."],[0,"(e) An application for a writ of habeas corpus in behalf of a prisoner who is authorized to apply for relief by motion pursuant to this section, shall not be entertained if it appears that the applicant has failed to apply for relief, by motion, to the court which sentenced him, or that such court has denied him relief, unless it also appears that the remedy by motion is inadequate or ineffective to test the legality of his detention."],[0,"(f) A 1-year period of limitation shall apply to a motion under this section. The limitation period shall run from the latest of—"],[1,"(1) the date on which the judgment of conviction becomes final;"],[1,"(2) the date on which the impediment to making a motion created by governmental action in violation of the Constitution or laws of the United States is removed, if the movant was prevented from making a motion by such governmental action;"],[1,"(3) the date on which the right asserted was initially recognized by the Supreme Court, if that right has been newly recognized by the Supreme Court and made retroactively applicable to cases on collateral review; or"],[1,"(4) the date on which the facts supporting the claim or claims presented could have been discovered through the exercise of due diligence."],[0,"(g) Except as provided in section 408 of the Controlled Substances Act, in all proceedings brought under this section, and any subsequent proceedings on review, the court may appoint counsel, except as provided by a rule promulgated by the Supreme Court pursuant to statutory authority. Appointment of counsel under this section shall be governed by section 3006A of title 18."],[0,"(h) A second or successive motion must be certified as provided in section 2244 by a panel of the appropriate court of appeals to contain—"],[1,"(1) newly discovered evidence that, if proven and viewed in light of the evidence as a whole, would be sufficient to establish by clear and convincing evidence that no reasonable factfinder would have found the movant guilty of the offense; or"],[1,"(2) a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2255?type=usc&year=mostrecent&link-type=html"},"op":168,"ar":3,"head":"§2255. Federal custody; remedies on motion attacking sentence","tname":"Judiciary and Judicial Procedure","by":{"0":"passim, passim, passim, passim, passim","1":"16, 16, 16, 16, 16, 16","2":"passim, 5, 6, 7, passim, 10"}},{"t":"law","label":"An Act to Implement the Recommendations of the Federal Courts Study Committee, and for Other Purposes, Pub. L. No. 102-572","url":"https://www.govinfo.gov/link/statute/106/4506","by":{"0":"31-32"}},{"t":"law","label":"An Act to Provide for the Admission of the State of Alaska Into the Union, Pub. L. No. 85-508","url":"https://www.govinfo.gov/link/statute/72/339","by":{"0":"32"}},{"t":"law","label":"An Act to Provide for the Admission of the State of Hawaii into the Union, Pub. L. No. 86-3","url":"https://www.govinfo.gov/link/statute/73/4","by":{"0":"32"}},{"t":"law","label":"and Other Provisions: Antiterrorism and Effective Death Penalty Act, Pub. L. No. 104-132","url":"https://www.govinfo.gov/link/plaw/104/public/132","by":{"0":"4","1":"7, 25"}},{"t":"rule","label":"Fed. R. Civ. P. 2","url":"https://www.law.cornell.edu/rules/frcp/rule_2","by":{"0":"24"}},{"t":"case","label":"Brown v. Davenport","cite":"142 S. Ct. 1510","y":2022,"id":"2021/20-826","sc":1,"op":7,"sum":"When a state court has ruled on the merits of a state prisoner’s claim, a federal court cannot grant habeas relief without applying both the test this Court outlined in Brecht v. Abrahamson, 507 U. S. 619, and the one Congress prescribed in the Antiterrorism and Effective Death Penalty Act of 1996; the Sixth Circuit erred in granting habeas relief to Mr. Davenport based solely on its assessment that he could satisfy the Brecht standard.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"20, 23, 25"}},{"t":"case","label":"Calderon v. Thompson","cite":"523 U.S. 538","y":1998,"id":"1997/97-215","sc":1,"op":1,"sum":"The Court held that although it was consistent with the Antiterrorism and Effective Death Penalty Act of 1996, the recall was a grave abuse of discretion.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"Coleman v. Thompson","cite":"501 U.S. 722","y":1991,"id":"1990/89-7662","sc":1,"op":1,"ar":1,"sum":"Coleman's claims presented for the first time in the state habeas proceeding are not subject to review in federal habeas.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23"}},{"t":"case","label":"Dietz v. Bouldin","cite":"579 U.S. 40","y":2016,"id":"2015/15-458","sc":1,"sum":"The Court determined that a federal district court judge has some ability to recall jurors in a civil case after identifying an error in their verdict, subject to certain limitations to ensure the jurors were not prejudiced.","sumSrc":"Oyez","by":{"1":"41"}},{"t":"case","label":"Dretke v. Haley","cite":"541 U.S. 386","y":2004,"id":"2003/02-1824","sc":1,"sum":"The Court declined to answer the question presented, ruling instead that the district court should have first considered the ineffective assistance of counsel claim before reaching the question of whether the \"actual innocence\" exception applies to non-capital cases.","sumSrc":"Oyez","by":{"1":"30, 31"}},{"t":"case","label":"Estelle v. McGuire","cite":"502 U.S. 62","y":1991,"id":"1991/90-1074","sc":1,"op":2,"sum":"Neither the admission of the challenged evidence nor the jury instruction as to its use rises to the level of a due process violation.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"28"}},{"t":"case","label":"Greer v. United States","cite":"141 S. Ct. 2090","y":2021,"id":"2020/19-8709","sc":1,"sum":"In felon-in-possession cases under 18 U. S. C. §922(g)(1), an error under Rehaif v. United States, 588 U. S. ___, is not a basis for plain-error relief unless the defendant first makes a sufficient argument or representation on appeal that he would have presented evidence at trial that he did not in fact know he was a felon.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"32, 33, 34"}},{"t":"case","label":"Gutknecht v. United States","cite":"396 U.S. 295","y":1970,"id":"1969/71","sc":1,"ar":1,"sum":"While petitioner's I-A Selective Service classification was on appeal from the local board's denial of his application for exemption as a conscientious objector, petitioner surrendered his registration certificate and classification notice by leaving them, along with a statement against the war in Vietnam, on the steps of the federal building. The State Board denied the exemption and classified petitioner I-A. He …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20","2":"18"}},{"t":"case","label":"Hamm v. City of Rock Hill","cite":"379 U.S. 306","y":1964,"id":"1964/2","sc":1,"sum":"The Court held in a combined case that sit-in demonstrations could not be the subject of federal or state trespass prosecutions, and that any such convictions on appeal must be reversed.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Hill v. United States","cite":"368 U.S. 424","y":1962,"id":"1961/68","sc":1,"op":2,"sum":"In a Federal District Court, petitioner was convicted of two federal crimes and sentenced to imprisonment. He was represented by counsel both at the trial and when sentence was imposed; but, before imposing sentence, the judge failed to comply with the requirement of Rule 32 (a) of the Federal Rules of Criminal Procedure that he afford petitioner an opportunity to make a statement in his own behalf. Petitioner took …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"17, 20"}},{"t":"case","label":"Holland v. Florida","cite":"560 U.S. 631","y":2010,"id":"2009/09-5327","sc":1,"op":9,"ar":2,"sum":"The Court held that a state prisoner who has exhausted their appeals process in their state has one year to file a writ of habeas corpus, with certain exceptions (including attorney misconduct) that may allow the courts to relax that deadline.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"INS v. St. Cyr","cite":"533 U.S. 289","y":2001,"id":"2000/00-767","sc":1,"op":8,"sum":"The Court held that habeas jurisdiction was not repealed by AEDPA and IIRIRA.","sumSrc":"Oyez","by":{"1":"44"}},{"t":"case","label":"Kemp v. United States","cite":"142 S. Ct. 1856","y":2022,"id":"2021/21-5726","sc":1,"sum":"The term “mistake” in Federal Rule of Civil Procedure 60(b)(1) includes a judge’s errors of law; because Kemp’s motion alleged such an error, it was cognizable under Rule 60(b)(1) and untimely under Rule 60(c)’s 1-year limitations period.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"40"}},{"t":"case","label":"Kuhlmann v. Wilson","cite":"477 U.S. 436","y":1986,"id":"1985/84-1479","sc":1,"op":1,"ar":1,"sum":"The judgment is reversed, and the case is remanded. 742 F. 2d 741, reversed and remanded. JUSTICE POWELL delivered the opinion of the Court with respect to Parts I, IV, and V, concluding that the Court of Appeals erred in holding that respondent was entitled to relief under United States v. Henry, supra, which left open the question whether the Sixth Amendment forbids admission in evidence of an accused's statements …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23"}},{"t":"case","label":"Martinez v. Ryan","cite":"566 U.S. 1","y":2012,"id":"2011/10-1001","sc":1,"sum":"The Court held that a defendant who is prohibited by state law from raising a claim of ineffective assistance of counsel may establish cause for such a claim at trial by showing evidence of ineffective assistance up to that point.","sumSrc":"Oyez","by":{"1":"23"}},{"t":"case","label":"McCleskey v. Zant","cite":"499 U.S. 467","y":1991,"id":"1990/89-7024","sc":1,"op":2,"ar":2,"sum":"McCleskey's failure to raise his Massiah claim in his first federal habeas petition constituted abuse of the writ.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23, 29","2":"20"}},{"t":"case","label":"McQuiggin v. Perkins","cite":"569 U.S. 383","y":2013,"id":"2012/12-126","sc":1,"op":6,"ar":4,"sum":"The Court held that proving actual innocence allows a petitioner to pursue habeas corpus relief regardless of a statute of limitations.","sumSrc":"Oyez","by":{"1":"passim"}},{"t":"case","label":"Musacchio v. United States","cite":"577 U.S. 237","y":2016,"id":"2015/14-1095","sc":1,"sum":"The Court determined that the law of the case doctrine does not require that the sufficiency of evidence be measured against the elements laid out in the jury instructions when those elements require the government to prove more than the statute requires and the government did not object at trial. The Court also determined that a statute of limitations defense that is not raised at trial is not reviewable on appeal.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Neder v. United States","cite":"527 U.S. 1","y":1999,"id":"1998/97-1985","sc":1,"sum":"The Court held 6-3 that under the harmless-error rule, which applies to a jury instruction that omits an element of an offense, the trial court's error did not render Neder's trial \"fundamentally unfair.\" Thus, the error was harmless.","sumSrc":"Oyez","by":{"1":"21"}},{"t":"case","label":"Nichols v. United States","cite":"578 U.S. 104","y":2016,"id":"2015/15-5238","sc":1,"sum":"The Court determined that the Sexual Offender Registration and Notification Act does not require a sex offender who is moving to a country outside of U.S. jurisdiction to update his residence with the sexual offender registry.","sumSrc":"Oyez","by":{"1":"15, 37"}},{"t":"case","label":"Rumsfeld v. Padilla","cite":"542 U.S. 426","y":2004,"id":"2003/03-1027","sc":1,"op":1,"sum":"Instead, in 5-to-4 opinion written by Chief Justice William H. Rehnquist, the Court found that the case had been improperly filed. Under federal law, a petition for a writ of habeas corpus can only be filed against the person directly responsible for a prisoner's confinement or, put another way, the person with the power to bring the prisoner to court.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"Sanders v. United States","cite":"373 U.S. 1","y":1963,"id":"1962/202","sc":1,"op":5,"sum":"Noting that a prisoner may “deliberately withhol[d]” or “deliberately abando[n]” claims in a frst postconviction petition “in the hope of being granted two hearings rather than one”.","sumSrc":"opinion","by":{"1":"17, 29, 38"}},{"t":"case","label":"Schlup v. Delo","cite":"513 U.S. 298","y":1995,"id":"1994/93-7901","sc":1,"op":3,"ar":2,"sum":"Petitioner Schlup, a Missouri prisoner, was convicted of participating in the murder of a fellow inmate and sentenced to death. In this, his second federal habeas petition, he alleged that constitutional error at his trial deprived the jury of critical evidence that would have established his innocence. The District Court declined to reach the petition's merits, holding that Schlup could not satisfy the threshold …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24, 34, 35"}},{"t":"case","label":"Sunal v. Large","cite":"332 U.S. 174","y":1947,"id":"scdb/1946-132","sc":1,"op":5,"sum":"He could not later obtain a review of his conviction by a habeas corpus proceeding.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21, 22, 31"}},{"t":"case","label":"Swain v. Pressley","cite":"430 U.S. 372","y":1977,"id":"1976/75-811","sc":1,"op":3,"ar":3,"sum":"Holding a District of Columbia-court remedy modeled on § 2255 not to be “ `inadequate or ineffective' ” because the D. C. courts were “competent to decide all issues”.","sumSrc":"opinion","by":{"1":"18"}},{"t":"case","label":"Taylor v. Gilkey","cite":"314 F.3d 832","y":2002,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/314/832/","by":{"1":"41, 42"}},{"t":"case","label":"Triestman v. United States","cite":"124 F.3d 361","y":1997,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/124/361/","op":5,"by":{"1":"10","2":"3"}},{"t":"case","label":"United States v. Cotton","cite":"535 U.S. 625","y":2002,"id":"2001/01-687","sc":1,"sum":"The Court held that the omission from a federal indictment of a fact that enhances the statutory maximum sentence does not justify a Court of Appeals' vacating the enhanced sentence, even though the defendant did not object in the trial court.","sumSrc":"Oyez","by":{"1":"45"}},{"t":"case","label":"United States v. Jones","cite":"275 F.3d 673","y":2001,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/275/673/","by":{"1":"4"}},{"t":"case","label":"United States v. Throckmorton","cite":"98 U.S. 61","y":1878,"id":"scdb/1878-047","sc":1,"sum":"Explaining that “equity” does not “interfere to grant a trial of a matter which has already been discussed in a court of law”.","sumSrc":"brief:1","by":{"1":"43"}},{"t":"case","label":"United States v. Williams","cite":"341 U.S. 58","y":1951,"id":"scdb/1950-062","sc":1,"sum":"In a prosecution for violation of what is now 18 U. S. C. § 242, arising out of the alleged beating of persons to coerce confessions, and for conspiracy against Fourteenth Amendment rights of citizens in alleged violation of what is now 18 U. S. C. § 241, appellee Williams was convicted and the other three appellees were acquitted of the substantive offenses, and the jury was unable to agree on a verdict on the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"45"}},{"t":"const","label":"Amendment XIV","clauses":[["due-process-14","Due Process Clause (Fourteenth Amendment)"]],"by":{"1":"46"}},{"t":"usc","label":"1 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/1/1","stext":{"head":"§1. Words denoting number, gender, and so forth","paras":[[0,"In determining the meaning of any Act of Congress, unless the context indicates otherwise—"],[1,"words importing the singular include and apply to several persons, parties, or things;"],[1,"words importing the plural include the singular;"],[1,"words importing the masculine gender include the feminine as well;"],[1,"words used in the present tense include the future as well as the present;"],[1,"the words \"insane\" and \"insane person\" shall include every idiot, insane person, and person non compos mentis;"],[1,"the words \"person\" and \"whoever\" include corporations, companies, associations, firms, partnerships, societies, and joint stock companies, as well as individuals;"],[1,"\"officer\" includes any person authorized by law to perform the duties of the office;"],[1,"\"signature\" or \"subscription\" includes a mark when the person making the same intended it as such;"],[1,"\"oath\" includes affirmation, and \"sworn\" includes affirmed;"],[1,"\"writing\" includes printing and typewriting and reproductions of visual symbols by photographing, multigraphing, mimeographing, manifolding, or otherwise."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/1/1?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1. Words denoting number, gender, and so forth","tname":"General Provisions","by":{"1":"15, 37"}},{"t":"usc","label":"28 U.S.C. § 2244","url":"https://www.law.cornell.edu/uscode/text/28/2244","subs":["(b)(2)","(b)(2)(A)","(b)(2)(B)"],"stext":{"head":"§2244. Finality of determination","paras":[[0,"(a) No circuit or district judge shall be required to entertain an application for a writ of habeas corpus to inquire into the detention of a person pursuant to a judgment of a court of the United States if it appears that the legality of such detention has been determined by a judge or court of the United States on a prior application for a writ of habeas corpus, except as provided in section 2255."],[0,"(b)(1) A claim presented in a second or successive habeas corpus application under section 2254 that was presented in a prior application shall be dismissed."],[0,"(2) A claim presented in a second or successive habeas corpus application under section 2254 that was not presented in a prior application shall be dismissed unless—"],[1,"(A) the applicant shows that the claim relies on a new rule of constitutional law, made retroactive to cases on collateral review by the Supreme Court, that was previously unavailable; or"],[1,"(B)(i) the factual predicate for the claim could not have been discovered previously through the exercise of due diligence; and"],[1,"(ii) the facts underlying the claim, if proven and viewed in light of the evidence as a whole, would be sufficient to establish by clear and convincing evidence that, but for constitutional error, no reasonable factfinder would have found the applicant guilty of the underlying offense."],[0,"(3)(A) Before a second or successive application permitted by this section is filed in the district court, the applicant shall move in the appropriate court of appeals for an order authorizing the district court to consider the application."],[0,"(B) A motion in the court of appeals for an order authorizing the district court to consider a second or successive application shall be determined by a three-judge panel of the court of appeals."],[0,"(C) The court of appeals may authorize the filing of a second or successive application only if it determines that the application makes a prima facie showing that the application satisfies the requirements of this subsection."],[0,"(D) The court of appeals shall grant or deny the authorization to file a second or successive application not later than 30 days after the filing of the motion."],[0,"(E) The grant or denial of an authorization by a court of appeals to file a second or successive application shall not be appealable and shall not be the subject of a petition for rehearing or for a writ of certiorari."],[0,"(4) A district court shall dismiss any claim presented in a second or successive application that the court of appeals has authorized to be filed unless the applicant shows that the claim satisfies the requirements of this section."],[0,"(c) In a habeas corpus proceeding brought in behalf of a person in custody pursuant to the judgment of a State court, a prior judgment of the Supreme Court of the United States on an appeal or review by a writ of certiorari at the instance of the prisoner of the decision of such State court, shall be conclusive as to all issues of fact or law with respect to an asserted denial of a Federal right which constitutes ground for discharge in a habeas corpus proceeding, actually adjudicated by the Supreme Court therein, unless the applicant for the writ of habeas corpus shall plead and the court shall find the existence of a material and controlling fact which did not appear in the record of the proceeding in the Supreme Court and the court shall further find that the applicant for the writ of habeas corpus could not have caused such fact to appear in such record by the exercise of reasonable diligence."],[0,"(d)(1) A 1-year period of limitation shall apply to an application for a writ of habeas corpus by a person in custody pursuant to the judgment of a State court. The limitation period shall run from the latest of—"],[1,"(A) the date on which the judgment became final by the conclusion of direct review or the expiration of the time for seeking such review;"],[1,"(B) the date on which the impediment to filing an application created by State action in violation of the Constitution or laws of the United States is removed, if the applicant was prevented from filing by such State action;"],[1,"(C) the date on which the constitutional right asserted was initially recognized by the Supreme Court, if the right has been newly recognized by the Supreme Court and made retroactively applicable to cases on collateral review; or"],[1,"(D) the date on which the factual predicate of the claim or claims presented could have been discovered through the exercise of due diligence."],[0,"(2) The time during which a properly filed application for State post-conviction or other collateral review with respect to the pertinent judgment or claim is pending shall not be counted toward any period of limitation under this subsection."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2244?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2244. Finality of determination","tname":"Judiciary and Judicial Procedure","by":{"1":"16, 16, 16, 16"}},{"t":"case","label":"Adam v. Hagan","cite":"325 F.2d 719","y":1963,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/325/719/","by":{"2":"3"}},{"t":"case","label":"Bailey v. United States","cite":"516 U.S. 137","y":1995,"id":"1995/94-7448","sc":1,"op":2,"sum":"Describing the Circuits' approaches.","sumSrc":"opinion","by":{"2":"21-22"}},{"t":"case","label":"Black v. United States","cite":"301 F.2d 418","y":1962,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/301/418/","by":{"2":"3"}},{"t":"case","label":"Cohen v. United States","cite":"593 F.2d 766","y":1979,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/593/766/","by":{"2":"5"}},{"t":"case","label":"Crismond v. Blackwell","cite":"333 F.2d 374","y":1964,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/333/374/","by":{"2":"3"}},{"t":"case","label":"Cutter v. Wilkinson","cite":"544 U.S. 709","y":2005,"id":"2004/03-9877","sc":1,"op":1,"sum":"The Court held that, on its face, RLUIPA made an accommodation allowed by the First Amendment. The Court reasoned that the law was an effort to alleviate the \"government-created burden\" on religious exercise that prisoners faced. Nor did section three discriminate between mainstream and non-mainstream religions.","sumSrc":"Oyez","by":{"2":"20"}},{"t":"case","label":"Edwards v. Walker","cite":"349 F. Supp. 1295","y":1972,"court":"C.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp./349/1295/","by":{"2":"3"}},{"t":"case","label":"Mead v. Parker","cite":"464 F.2d 1108","y":1972,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/464/1108/","op":1,"by":{"2":"5"}},{"t":"case","label":"Ortiz v. United States","cite":"138 S. Ct. 2165","y":2018,"id":"2017/16-1423","sc":1,"ar":3,"sum":"The Court held that it has jurisdiction to review the CAAF's decisions and that Judge Martin T. Mitchell’s simultaneous service on the US Court of Military Commission Review (CMCR) and the US Air Force Court of Criminal Appeals (AFCCA) does not violate the Appointments Clause or 10 U.S.C. § 973(b)(2)(A).","sumSrc":"Oyez","by":{"2":"8"}},{"t":"case","label":"Reed v. Farley","cite":"512 U.S. 339","y":1994,"id":"1993/93-5418","sc":1,"op":1,"sum":"The judgment is affirmed. 984 F. 2d 209, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"Reed v. Ross","cite":"468 U.S. 1","y":1984,"id":"1983/83-218","sc":1,"sum":"Respondent had \"cause\" for failing to raise the Mullaney issue on appeal from his conviction.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21, 22"}},{"t":"case","label":"Shaffer v. Heitner","cite":"433 U.S. 186","y":1977,"id":"1976/75-1812","sc":1,"sum":"Appellee, a nonresident of Delaware, filed a shareholder's derivative suit in a Delaware Chancery Court, naming as defendants a corporation and its subsidiary, as well as 28 present or former corporate officers or directors, alleging that the individual defendants had violated their duties to the corporation by causing it and its subsidiary to engage in actions (which occurred in Oregon) that resulted in corporate …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"13"}},{"t":"case","label":"Smith v. Settle","cite":"302 F.2d 142","y":1962,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.2d/302/142/","by":{"2":"3"}},{"t":"case","label":"Solorio v. United States","cite":"483 U.S. 435","y":1987,"id":"1986/85-1581","sc":1,"sum":"The jurisdiction of a court-martial depends solely on the accused's status as a member of the Armed Forces, and not on the \"service connection\" of the offense charged. Thus, O'Callahanis overruled. The plain meaning of Art. I, § 8, cl. 14, of the Constitution-which grants Congress plenary power \"[t]o make Rules for the Government and Regulation of the land and naval Forces\"-supports the military status test, as was …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"8"}},{"t":"case","label":"Stidham v. Swope","cite":"82 F. Supp. 931","y":1949,"court":"N.D. Cal","url":"https://www.courtlistener.com/c/F.%20Supp./82/931/","op":1,"sum":"Describing the diffculty and delay involved in transporting a prisoner “upwards of 1,500 miles” from the federal penitentiary in Alcatraz to the sentencing court in Missouri, a journey that “well could be two weeks” by rail.","sumSrc":"opinion","by":{"2":"3, 4"}},{"t":"case","label":"Strickler v. Greene","cite":"527 U.S. 263","y":1999,"id":"1998/98-5864","sc":1,"sum":"The Court held that although Strickler demonstrated cause for his failure to raise a Brady claim, Virginia did not violate Brady by failing to disclose exculpatory evidence to him.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Trevino v. Thaler","cite":"569 U.S. 413","y":2013,"id":"2012/11-10189","sc":1,"op":1,"sum":"The Court found that procedural default will not bar a federal court from hearing a claim of ineffective assistance of trial counsel.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"United States v. Fox","cite":"454 F.2d 593","y":1971,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/454/593/","op":1,"by":{"2":"19"}},{"t":"case","label":"United States v. Frady","cite":"456 U.S. 152","y":1982,"id":"1981/80-1595","sc":1,"sum":"In 1963, respondent was convicted of first-degree murder and sentenced to death by a jury in the Federal District Court for the District of Columbia, which at that time had exclusive jurisdiction over local felonies committed in the District. The Court of Appeals for the District of Columbia Circuit, which then acted as the local appellate court, upheld the conviction but set aside the death sentence, and respondent …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"Williams v. United States","cite":"323 F.2d 672","y":1963,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/323/672/","by":{"2":"3"}},{"t":"usc","label":"10 U.S.C. § 941","url":"https://www.law.cornell.edu/uscode/text/10/941","subs":["(2016)"],"by":{"2":"9, 9"}}]};